function titleFromKeyword(kw,topic){if(kw.length<=70)return kw;const ctx=topic.decisionContext?` ${topic.decisionContext}`:'';const base=`${topic.intentLabel} ${topic.category} نون ${topic.market}${ctx} ${topic.scenario}`;return base.length<=70?base.slice(0,70):`${topic.category} نون ${topic.market}${ctx}: ${topic.scenario}`.slice(0,70)}
function metaFor(t){const ctx=t.decisionContext?`، ${t.decisionContext}`:'';let s=`${t.kw}: دليل عملي في نون ${t.market} يوضح فحص ${t.factor}${ctx}، تجربة ${t.code}، مقارنة البائع والسعر النهائي، وما يجب مراجعته قبل الدفع.`;if(s.length<110)s+=' مع خطوات واضحة للمقارنة واتخاذ قرار شراء مناسب.';return s.slice(0,160)}
function image(t,v,role){const src=`/assets/coupon-svg/${encodeURIComponent(t.slug)}/${v}.svg?v=9&coupon=${encodeURIComponent(t.code)}&country=${t.country}`;return `<figure class="article-visual visual-${v}"><img src="${src}" alt="${esc(t.kw)} — ${esc(role)} — ${t.code}" title="${esc(t.category)}: ${esc(role)}" width="1200" height="760" loading="lazy" decoding="async"><figcaption>${esc(role)} لـ${esc(t.category)} في نون ${esc(t.market)} عند تجربة ${t.code}</figcaption></figure>`}

function sectionFactors(t){const f=t.factors;return `<section><h2>ما المعايير التي تستحق المقارنة في ${t.category}؟</h2><p>قبل التفكير في القسيمة، ثبّت ما تحتاجه فعلًا في ${t.category}. في حالة ${t.useCase}، ركّز أولًا على ${f[0]} و${f[1]}، ثم راجع ${f[2]}. هذه العوامل تستطيع تغيير قيمة الشراء أكثر من مجرد وجود كود؛ لذلك لا تغيّر المنتج فقط لأن سلة أخرى قبلت القسيمة.</p><p>اكتب معيار استبعاد واضحًا لكل نقطة: إذا لم يحقق المنتج الحد المقبول في ${t.factor} فلا تعتبر الخصم سببًا كافيًا لاختياره. بعد ذلك استخدم ${f[3]} و${f[4]} كعوامل ترجيح بين المنتجات التي اجتازت الشروط الأساسية.</p><ul><li>شرط أساسي: ${f[0]} بما يناسب ${t.useCase}.</li><li>عامل مقارنة: ${f[1]} بين الخيارات المتقاربة.</li><li>تحقق قبل الدفع: ${t.checks[0]}.</li><li>تحقق بعد اختيار المنتج: ${t.checks[1]}.</li></ul></section>`}
function sectionCoupon(t){return `<section><h2>كيف تختبر ${t.code} بدون أن تخلط بين الخصم والسعر؟</h2><p>ابنِ سلة ثابتة أولًا، ثم دوّن الإجمالي قبل تطبيق الكود. انسخ <strong>${t.code}</strong> كما هو، وطبّقه مرة واحدة، وبعد تحديث السلة راجع قيمة الطلب النهائية ورسوم الشحن والبائع. إذا تغيّر المنتج أو الكمية أثناء التجربة، أعد القياس من البداية لأن المقارنة لم تعد على السلة نفسها.</p><p class="atomic-answer"><strong>إجابة سريعة:</strong> نجاح إدخال الكود لا يكفي وحده؛ القرار الصحيح يعتمد على الإجمالي النهائي لنفس السلة وعلى ملاءمة المنتج، وليس على رسالة قبول القسيمة فقط.</p><div class="coupon-actions"><button type="button" data-copy-code="${t.code}" aria-label="نسخ كود نون ${t.code}">نسخ ${t.code}</button><a href="https://www.noon.com/" rel="noopener external sponsored">تجربة الكود على نون الرسمي</a><span class="copy-feedback" aria-live="polite"></span></div></section>`}
function sectionScenario(t){return `<section><h2>كيف تتعامل مع سيناريو «${t.scenario}»؟</h2><p>في هذا السيناريو لا تغيّر عدة عوامل في وقت واحد. ثبّت المنتج والكمية والبائع، ثم راقب أثر تغيير واحد فقط. عند ${t.scenario} يصبح تتبع الإجمالي خطوة بخطوة مفيدًا لأنه يكشف هل الفرق جاء من القسيمة، من السعر الأساسي، من الشحن، أو من تغيير داخل السلة.</p><p>بالنسبة إلى ${t.useCase}، اسأل قبل إتمام الطلب: هل ${t.factor} مناسب فعلًا؟ وهل البديل الأرخص يحقق نفس الاحتياج؟ لو كانت الإجابة لا، فمطاردة فارق صغير في السعر قد تقلل قيمة الشراء بدل أن تحسنها.</p></section>`}
function sectionSeller(t){return `<section><h2>البائع والشحن والإرجاع جزء من السعر الحقيقي</h2><p>عند وجود أكثر من عرض لنفس ${t.category}، قارن مواصفات المنتج والبائع وموعد التوصيل وسياسة الإرجاع قبل مقارنة السعر. اختلاف الإصدار أو الحالة أو الملحقات قد يجعل منتجين متشابهين في الاسم غير متكافئين فعليًا.</p><p>راجع أيضًا ${t.checks[2]} و${t.checks[3]}. إذا كان عرض أقل سعرًا يضيف مخاطرة أو عبئًا لا يناسبك، ضعه في المقارنة بوضوح بدل تجاهل هذا الفرق. الهدف هو أقل تكلفة نهائية لخيار مناسب، لا أقل رقم ظاهر فقط.</p></section>`}
function sectionMarket(t){return `<section data-scope="national"><h2>ما الذي يختلف عند الشراء في نون ${t.market}؟</h2><p>هذا الدليل مخصص لسوق نون ${t.market}. عند مقارنة الأسعار استخدم ${t.currency} (${t.currencyCode})، وتأكد أن عنوان التسليم وإعداد الدولة يطابقان السوق قبل اختبار القسيمة. لا ننقل نتيجة كود من سوق آخر وكأنها نتيجة مؤكدة هنا.</p><p>يمكنك الرجوع إلى <a href="${t.marketPath}">صفحة نون ${t.market}</a> وإلى <a href="/coupons">صفحة الكوبونات</a> للمقارنة. أهلية ${t.code} والنتيجة النهائية تظل مرتبطة بما تعرضه سلة نون لحسابك وقت الطلب.</p></section>`}
function sectionEligibility(t){return `<section><h2>ما شروط الأهلية والاستبعاد التي يجب التحقق منها؟</h2><p>لا نفترض شروطًا غير منشورة ولا ندعي أن الكود يعمل لكل حساب أو منتج. قبل الدفع راجع أي رسالة تظهر في السلة، وتحقق من المنتج والكمية والبائع وطريقة الدفع والحساب. إذا ظهر شرط واضح داخل نون، فهو المرجع العملي لهذه المحاولة.</p><p>في ${t.category} راجع خصوصًا ${t.checks[0]} و${t.checks[1]}. لو تعارضت القسيمة مع اختيار المنتج المناسب، حافظ على احتياجك أولًا ثم قارن البدائل بدل تعديل السلة فقط لإجبار الكود على القبول.</p></section>`}
function sectionTrouble(t){return `<section><h2>ماذا تفعل إذا لم يعمل الكود أو تغير السعر؟</h2><p>ابدأ باستكشاف المشكلة بطريقة قابلة للقياس: تأكد من السوق، ثم من كتابة ${t.code}، وبعدها اختبر عنصرًا واحدًا من ${t.category}. إذا نجح الاختبار أضف بقية العناصر تدريجيًا. هذه الطريقة تساعدك على اكتشاف نقطة التغير من دون تخمين.</p><ol><li>ثبّت الحساب والسوق.</li><li>استخدم سلة صغيرة بمنتج واحد.</li><li>دوّن السعر قبل الكود وبعده.</li><li>غيّر عاملًا واحدًا فقط، مثل البائع أو الكمية.</li><li>إذا استمر الرفض، قيّم الصفقة بدون القسيمة أو جرّب خيارًا آخر بدل تكرار نفس المحاولة.</li></ol></section>`}
function sectionSavings(t){return `<section><h2>كيف تقيس التوفير الحقيقي بدل الانشغال بنسبة غير موثقة؟</h2><p>قارن أربعة عناصر: سعر المنتجات، الشحن، أي تخفيض ظاهر داخل السلة، والإجمالي النهائي. لا نضع نسبة خصم ثابتة أو حدًا أقصى غير موثق؛ لأن هذه التفاصيل قد تختلف حسب الحملة والحساب والمنتج ووقت الشراء.</p><p class="atomic-answer"><strong>قاعدة عملية:</strong> إذا كان خيار آخر يحقق احتياج ${t.useCase} بتكلفة نهائية أقل وبشروط بائع وإرجاع مناسبة، فهو قد يكون أفضل حتى لو لم يستخدم نفس القسيمة.</p></section>`}
function sectionMatrix(t){return `<section><h2>مصفوفة قرار سريعة قبل إتمام الطلب</h2><table><thead><tr><th>ما تفحصه</th><th>لماذا يهم؟</th><th>قرارك</th></tr></thead><tbody><tr><td>${t.factors[0]}</td><td>يحدد صلاحية المنتج لـ${t.useCase}</td><td>شرط أساسي</td></tr><tr><td>${t.factor}</td><td>يفرق بين بدائل متقاربة</td><td>عامل ترجيح</td></tr><tr><td>البائع والإرجاع</td><td>يؤثران في قيمة الصفقة بعد الشراء</td><td>تحقق قبل الدفع</td></tr><tr><td>الإجمالي بعد ${t.code}</td><td>يكشف الأثر الفعلي داخل السلة</td><td>قارن على نفس السلة</td></tr></tbody></table><p>استخدم الجدول كقائمة قصيرة، ولا تمنح الكود وزنًا أكبر من المنتج نفسه. إذا فشل شرط أساسي، استبعد الخيار حتى لو بدا سعره جذابًا.</p></section>`}
const SECTION={factors:sectionFactors,coupon:sectionCoupon,scenario:sectionScenario,seller:sectionSeller,market:sectionMarket,eligibility:sectionEligibility,trouble:sectionTrouble,savings:sectionSavings,matrix:sectionMatrix};

function exampleSection(t){return `<section><h2>مثال تطبيقي على المقارنة قبل الدفع</h2><p>افترض أنك وجدت خيارين من ${t.category} مناسبين لـ${t.useCase}. ابدأ بالخيار الذي يحقق ${t.factors[0]} و${t.factor} بصورة أفضل، ثم ثبّت الكمية والبائع لكل تجربة. سجّل السعر الأساسي والشحن، وبعدها جرّب ${t.code} على السلة نفسها. إذا تحسن الإجمالي لكن الخيار الآخر ما زال أوفر أو أوضح في الإرجاع، لا تعتبر قبول الكود وحده سببًا لتغيير القرار.</p><p>هذا المثال لا يفترض سعرًا أو خصمًا ثابتًا؛ فائدته أنه يعطيك طريقة قابلة للتكرار. عندما تتغير نتيجة السلة، تستطيع الرجوع إلى الأرقام التي سجلتها ومعرفة العامل الذي تغير بدل الاعتماد على الانطباع.</p></section>`}
function finalSection(t){return `<section><h2>القرار النهائي: متى تكمل الشراء؟</h2><p>أكمل عندما يكون ${t.category} مناسبًا لـ${t.useCase}، وتكون نقاط ${t.factor} والبائع والإرجاع واضحة، ويظل الإجمالي النهائي داخل ميزانيتك بعد مراجعة السلة. إذا كان القرار يعتمد فقط على وجود القسيمة، أعد المقارنة من البداية على المنتج نفسه.</p><p>يمكنك الانتقال إلى <a href="/categories">التصنيفات</a> أو <a href="/blog">أحدث الأدلة</a> أو <a href="/guides">الأدلة</a> لمراجعة موضوعات مرتبطة قبل الدفع.</p><div class="coupon-actions bottom"><button type="button" data-copy-code="${t.code}" aria-label="نسخ كود نون ${t.code} من نهاية المقال">نسخ ${t.code}</button><a href="https://www.noon.com/" rel="noopener external sponsored">فتح نون الرسمي وتجربة الكود</a><span class="copy-feedback" aria-live="polite"></span></div></section>`}
function methodologySection(t){return `<section class="methodology accountability"><h2>منهجية التحقق والمراجعة التحريرية</h2><p><strong>الناشر:</strong> كوبونات نون (NoonCoupons). <strong>المراجع:</strong> فريق تحرير NoonCoupons. <strong>آخر مراجعة:</strong> <time datetime="${nowDate()}">${nowDate()}</time>. نعتمد على فصل قرار المنتج عن نتيجة القسيمة، ونعتبر السلة وشروط نون الحالية المرجع النهائي لأي أهلية أو سعر متغير.</p><p>هذا المحتوى لا يدعي اختبار كل حساب ولا يَعِد بنتيجة ثابتة. نقارن خطوات الاستخدام، سلامة السوق والكود، وضوح القرار، وروابط المصدر؛ ثم تمنع بوابة الجودة النشر إذا ظهر تضارب في البلد أو الكوبون أو ادعاء ترويجي غير موثق.</p></section>`}
function sourcesSection(t){return `<section class="sources"><h2>المصدر وشفافية المعلومات</h2><p>مصدر التحقق التجاري النهائي هو <a href="https://www.noon.com/" rel="noopener external sponsored">موقع نون الرسمي</a> وما يظهر داخل سلة حسابك وقت الطلب. قائمة الأكواد المستخدمة في هذا النظام مقدمة من مالك الموقع، ونستخدم ${t.code} ككود متاح للتجربة لا كوعد بنسبة خصم أو أهلية ثابتة.</p></section>`}
function faqSection(t){const faq=[{q:`كيف أستخدم ${t.code} على نون ${t.market}؟`,a:`ثبّت السلة أولًا، انسخ ${t.code} إلى خانة القسيمة، ثم راجع الإجمالي النهائي ورسوم الشحن والبائع قبل الدفع.`},{q:`هل ${t.code} مضمون لكل حساب؟`,a:`لا. لا ندعي ضمان الأهلية؛ ما تعرضه سلة نون وشروط الحملة الحالية هو المرجع النهائي للحساب والمنتج.`},{q:`ماذا أفعل إذا رُفض الكود عند شراء ${t.category}؟`,a:`اختبر منتجًا واحدًا، تأكد من السوق والحساب، ثم أضف العناصر تدريجيًا وغيّر عاملًا واحدًا في كل محاولة.`},{q:`كيف أعرف أن صفقة ${t.category} جيدة؟`,a:`قارن ملاءمة المنتج لـ${t.useCase} والبائع والإرجاع والشحن والإجمالي النهائي؛ لا تعتمد على وجود القسيمة وحدها.`},{q:`ما العمل إذا تغير السعر أثناء المقارنة؟`,a:`أعد تسجيل السعر الأساسي ثم أعد اختبار السلة نفسها، لأن فرق السعر لا يمكن نسبه للكود إذا تغير المنتج أو السعر الأصلي.`}];const visible=faq.map(x=>`<details><summary><h3>${esc(x.q)}</h3></summary><p>${esc(x.a)}</p></details>`).join('');const schema={'@context':'https://schema.org','@type':'FAQPage',mainEntity:faq.map(x=>({'@type':'Question',name:x.q,acceptedAnswer:{'@type':'Answer',text:x.a}}))};return {faq,html:`<section class="faq"><h2>الأسئلة الشائعة</h2>${visible}</section><script type="application/ld+json" data-schema="faq">${JSON.stringify(schema).replace(/</g,'\\u003c')}</script>`}}

