 const faq=[{q:`How do I use ${t.code} on Noon ${market}?`,a:`Copy ${t.code} into the coupon field, keep the cart stable and check the final total before payment.`},{q:`Is ${t.code} guaranteed for every account?`,a:'No. Eligibility can vary by the current cart, account and campaign conditions shown by Noon.'},{q:`What should I do if the coupon is rejected?`,a:'Confirm the market and code, test one item, then add other items gradually while changing one factor at a time.'},{q:`How should I compare ${cat} deals?`,a:'Compare product fit, seller, shipping, returns and the final payable total rather than coupon acceptance alone.'}];
