export function buildBulkTopic(cursor=0,options={}){
  const raw=Math.max(0,Number(cursor)||0),cycle=Math.floor(raw/BASE_TOPIC_SPACE)%DECISION_CONTEXTS.length,decisionContext=DECISION_CONTEXTS[cycle]||'';let q=((raw%BASE_TOPIC_SPACE)*7919+104729)%BASE_TOPIC_SPACE;
  const forcedCountry=String(options?.forceCountry||'').toUpperCase(),country=(forcedCountry==='AE'||forcedCountry==='SA')?forcedCountry:(raw%5===0?'AE':'SA');q=Math.floor(q/2);
  const prioritySlot=options?.independentPriority?(Math.floor(raw/5)%5<3):(raw%5<3),categoryPool=prioritySlot?PRIORITY_CATEGORIES:CATEGORIES;
  const [category,profileKey]=categoryPool[q%categoryPool.length];q=Math.floor(q/categoryPool.length);const [intentId,intentFn]=INTENTS[q%INTENTS.length];q=Math.floor(q/INTENTS.length);const scenario=SCENARIOS[q%SCENARIOS.length];q=Math.floor(q/SCENARIOS.length);const profile=PROFILES[profileKey],factor=profile.factors[q%profile.factors.length];q=Math.floor(q/profile.factors.length);const useCase=profile.uses[q%profile.uses.length],m=MARKETS[country],code=CODES[(Math.floor(raw/7)+q)%CODES.length];
  const labels={coupon:'كود خصم',howto:'استخدام كود',compare:'مقارنة سعر',trouble:'حل رفض الكود',question:'هل يعمل الكود',seller:'اختيار بائع',decision:'دليل شراء',finalprice:'السعر النهائي',value:'التوفير',cart:'مراجعة سلة',timing:'توقيت الكوبون',smartbuy:'شراء ذكي',eligibility:'شروط الكود',checklist:'خطوات قبل الدفع',multi:'شراء عدة منتجات',returns:'مراجعة الإرجاع',warranty:'فحص الضمان',budget:'اختيار بميزانية'};
  const topicBase={country,market:m.name,currency:m.currency,currencyCode:m.currencyCode,marketPath:m.path,category,profileKey,factors:profile.factors,checks:profile.checks,useCase,factor,scenario,decisionContext,code,intent:intentId,intentLabel:labels[intentId]||'دليل'};
  const baseKw=intentFn(topicBase).replace(/\s+/g,' ').trim(),kw=(decisionContext?baseKw+' '+decisionContext:baseKw).replace(/\s+/g,' ').trim(),variant='v'+cycle.toString(36),slugBase=slugify(kw),slug=cycle?slugBase.slice(0,Math.max(40,118-variant.length))+'-'+variant:slugBase;
  return {...topicBase,kw,slug,title:titleFromKeyword(kw,topicBase),topicIndex:raw,generationSeed:raw,baseVariantIndex:q,decisionCycle:cycle,totalTopicSpace:TOTAL_TOPIC_SPACE,commercialPriority:prioritySlot?'high':'standard'};
}

export function buildUsefulArticle(topic,cursor=0){
  const t={...topic},blueprint=cursor%BLUEPRINTS.length;t.title=titleFromKeyword(t.kw,t);t.slug=t.slug||slugify(t.kw);const contextNote=t.decisionContext?` وفي هذا الدليل نركز على ${t.decisionContext}.`:'';const direct=`إذا كان بحثك هو «${t.kw}»، فابدأ بصلاحية ${t.category} لـ${t.useCase} ثم راجع ${t.factor} والبائع والشحن.${contextNote} جرّب ${t.code} على سلة ثابتة في نون ${t.market}، واجعل الإجمالي النهائي هو المرجع بدل أي ادعاء غير موثق عن نسبة الخصم.`;
  let body=`<article lang="ar-${t.country}" dir="rtl" data-blueprint="${blueprint}" data-scope="national"><p class="eyebrow">${t.intentLabel} · نون ${t.market} · ${t.category}</p><h1>${esc(t.title)}</h1><p class="direct-answer"><strong>الخلاصة العملية:</strong> ${esc(direct)}</p><nav class="article-toc quick-nav" aria-label="روابط مساعدة"><a href="${t.marketPath}">سوق ${t.market}</a> · <a href="/coupons">الكوبونات</a> · <a href="/categories">التصنيفات</a> · <a href="/blog">المدونة</a> · <a href="/guides">الأدلة</a></nav>`;
  const roles=['صورة تعريف الكوبون والسوق','مخطط قرار قبل الدفع','تذكير بمراجعة السلة والبائع','ملخص خطوات تجربة الكود'];let vi=2,sectionIndex=0;for(const key of BLUEPRINTS[blueprint]){body+=SECTION[key](t);sectionIndex++;if([2,4,6,8].includes(sectionIndex)){body+=image(t,vi,roles[vi-2]);vi++}}
  const fq=faqSection(t);body+=exampleSection(t)+finalSection(t)+methodologySection(t)+sourcesSection(t)+fq.html+'</article>';return {slug:t.slug,title:t.title,metaDescription:metaFor(t),country:t.country,coupon:t.code,primaryKeyword:t.kw,blueprint,faq:fq.faq,sources:['https://www.noon.com/'],claims:[],html:body};
}

